def map_auto_tags_to_their_classic_tag(apps, schema_editor):
    """The tags automatic tagging placed before it remembered them: a tag
    carrying an automatic assignment under a classic tag's English name. The
    oldest wins when an owner has two spellings of one name."""
    Tag = apps.get_model("files", "Tag")
    FileTag = apps.get_model("files", "FileTag")
    ClassicTagMapping = apps.get_model("photos", "ClassicTagMapping")
    db = schema_editor.connection.alias
    auto_tag_ids = FileTag.objects.using(db).filter(source="auto").values("tag_id")
    tags = (
        Tag.objects.using(db)
        .annotate(folded=Lower("name"))
        .filter(folded__in=list(_LABELS), uuid__in=auto_tag_ids)
        .order_by("created_at")
        .values_list("owner_id", "folded", "uuid")
    )
    mappings = {}
    for owner_id, folded, tag_id in tags.iterator():
        mappings.setdefault((owner_id, _LABELS[folded]), tag_id)
    ClassicTagMapping.objects.using(db).bulk_create(
        [
            ClassicTagMapping(owner_id=owner_id, label=label, tag_id=tag_id)
            for (owner_id, label), tag_id in mappings.items()
        ],
        ignore_conflicts=True,
    )


